/**
 * Declaration for the .jsx component beside this file.
 *
 * The project compiles with `allowJs` off, so an untyped .jsx module cannot be
 * imported from TypeScript without one. Mirrors the approach already used for
 * the React Bits components in `react-bits.d.ts`.
 */
declare const FloatingContactButtons: () => JSX.Element
export default FloatingContactButtons
